// prisma schema
model User {
  id    Int    @id @default(autoincrement())
  email String @unique
  posts Post[]
}

@Entity()
class Post {
  @ManyToOne(() => User, (user) => user.posts)
  author: User;
}

@Injectable()
class UsersService {
  constructor(
    @InjectRepository(User)
    private repo: Repository<User>,
  ) {}
}

